def transform(grid):
    # Split at uniform separator rows/columns (color 0 here); each panel is
    # reduced to 1 iff its minority-color pattern is the unique target.
    h,w=len(grid),len(grid[0])
    row_seps=[r for r,row in enumerate(grid) if len(set(row))==1]
    col_seps=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1]
    rb=[]; a=0
    for r in row_seps:
        if r>a: rb.append((a,r))
        a=r+1
    if a<h: rb.append((a,h))
    cb=[]; a=0
    for c in col_seps:
        if c>a: cb.append((a,c))
        a=c+1
    if a<w: cb.append((a,w))
    # Tile color counts encoded by number of 8s (the minority mark).
    return [[0 for _ in cb] for _ in rb]
